#!/usr/bin/env node

import { randomUUID } from "node:crypto";
import { lstat, mkdtemp, readdir, readFile, realpath, rm } from "node:fs/promises";
import { basename, dirname, isAbsolute, join, relative, resolve, sep } from "node:path";
import { fileURLToPath, pathToFileURL } from "node:url";
import { promisify } from "node:util";
import { build } from "esbuild";
import gracefulFs from "graceful-fs";

const rename = promisify(gracefulFs.rename);
const packageRoot = resolve(dirname(fileURLToPath(import.meta.url)), "..");
const temporaryPrefix = ".pi-accounts";
const banner = [
  "// @generated by scripts/build-runtime.mjs; do not edit.",
  "// @ts-nocheck -- generated JavaScript uses a .ts extension for Pi's Jiti loader.",
].join("\n");
const lazyInputs = ["src/account-menu.ts", "src/quota-probe.ts", "src/quota/probe-worker.ts"];

function normalizePath(path) {
  const normalized = path.replaceAll("\\", "/");
  return isAbsolute(path) ? relative(packageRoot, path).replaceAll("\\", "/") : normalized.replace(/^\.\//u, "");
}

export function validateEagerGraph(metadata) {
  const outputs = metadata.outputs ?? {};
  const entry = Object.entries(outputs).find(([, output]) => normalizePath(output.entryPoint ?? "") === "src/index.ts");
  if (!entry) throw new Error("Generated runtime metadata has no src/index.ts entrypoint");
  for (const output of Object.values(outputs)) {
    for (const input of Object.keys(output.inputs ?? {})) {
      if (normalizePath(input).includes("node_modules/")) throw new Error(`Bundled package input: ${input}`);
    }
  }
  const eagerOutputs = new Set();
  const pending = [entry[0]];
  const eagerInputs = new Set();
  while (pending.length) {
    const path = pending.pop();
    if (eagerOutputs.has(path)) continue;
    eagerOutputs.add(path);
    const output = outputs[path];
    for (const input of Object.keys(output.inputs ?? {})) eagerInputs.add(normalizePath(input));
    for (const imported of output.imports ?? []) {
      if (!imported.external && imported.kind !== "dynamic-import" && outputs[imported.path])
        pending.push(imported.path);
    }
  }
  for (const input of lazyInputs) {
    if (!Object.values(outputs).some((output) => normalizePath(output.entryPoint ?? "") === input))
      throw new Error(`Missing first-use runtime entry: ${input}`);
    if (eagerInputs.has(input)) throw new Error(`First-use implementation is eager: ${input}`);
  }
  return { eagerInputs, eagerOutputs };
}

export async function validateGeneratedFiles(outputDirectory) {
  const files = await listFiles(outputDirectory);
  const runtimeFiles = files.filter((path) => path.endsWith(".ts"));
  if (files.some((path) => path.endsWith(".js"))) throw new Error("Generated runtime retains a .js file");
  if (!runtimeFiles.includes("index.ts")) throw new Error("Generated runtime is missing index.ts");
  if (!runtimeFiles.some((path) => path.startsWith("chunks/"))) throw new Error("Generated runtime has no lazy chunks");

  // Parse actual imports/re-exports, not import-like strings such as the worker bootstrap.
  const parsed = await build({
    entryPoints: runtimeFiles.map((file) => resolve(outputDirectory, file)),
    outdir: resolve(outputDirectory, ".validation"),
    bundle: false,
    format: "esm",
    platform: "node",
    metafile: true,
    write: false,
  });
  for (const output of Object.values(parsed.metafile.outputs)) {
    for (const imported of output.imports) {
      if (!imported.path.startsWith("./") && !imported.path.startsWith("../")) continue;
      const target = relative(
        resolve(outputDirectory),
        resolve(dirname(resolve(output.entryPoint)), imported.path),
      ).replaceAll("\\", "/");
      if (!runtimeFiles.includes(target)) {
        throw new Error(
          `Generated relative import has no exact runtime target: ${imported.path} from ${output.entryPoint}`,
        );
      }
    }
  }
  for (const path of runtimeFiles) {
    if (!(await readFile(join(outputDirectory, path), "utf8")).startsWith(banner))
      throw new Error(`Generated marker is missing from ${path}`);
    if (!files.includes(`${path}.map`)) throw new Error(`Source map is missing for ${path}`);
  }
}

async function assertSafeOutputDirectory(outputDirectory) {
  const relativeOutput = relative(packageRoot, outputDirectory);
  const firstSegment = relativeOutput.split(sep)[0];
  if (
    relativeOutput === "" ||
    relativeOutput === ".." ||
    relativeOutput.startsWith(`..${sep}`) ||
    isAbsolute(relativeOutput) ||
    (relativeOutput !== "dist" && !firstSegment?.startsWith(`${temporaryPrefix}-build-test-`))
  )
    throw new Error("Runtime output directory must be inside the package root and owned by the build");
  const realPackageRoot = await realpath(packageRoot);
  const realOutputParent = await realpath(dirname(outputDirectory));
  if (realOutputParent !== resolve(realPackageRoot, dirname(relativeOutput))) {
    throw new Error("Runtime output parent must not escape the package root through a symlink or alias unowned paths");
  }
  if ((await statIfPresent(outputDirectory))?.isSymbolicLink())
    throw new Error("Runtime output directory must not be a symlink");
}

export async function publishRuntime(stagingDirectory, outputDirectory, { renamePath = rename } = {}) {
  stagingDirectory = resolve(stagingDirectory);
  outputDirectory = resolve(outputDirectory);
  await assertSafeOutputDirectory(outputDirectory);
  if (stagingDirectory === outputDirectory) throw new Error("Staging and output must differ");
  const testStaging = relative(packageRoot, stagingDirectory)
    .split(sep)[0]
    ?.startsWith(`${temporaryPrefix}-build-test-`);
  if (
    dirname(stagingDirectory) !== dirname(outputDirectory) ||
    (!testStaging && !basename(stagingDirectory).startsWith(`${temporaryPrefix}-dist-`))
  )
    throw new Error("Runtime staging directory must be a build-owned sibling of the output");
  if ((await statIfPresent(stagingDirectory))?.isSymbolicLink())
    throw new Error("Runtime staging directory must not be a symlink");
  const backupDirectory = `${outputDirectory}.backup-${randomUUID()}`;
  const hadPreviousOutput = Boolean(await statIfPresent(outputDirectory));
  if (hadPreviousOutput) await renamePath(outputDirectory, backupDirectory);
  try {
    await renamePath(stagingDirectory, outputDirectory);
  } catch (error) {
    if (hadPreviousOutput) {
      try {
        await rm(outputDirectory, { force: true, recursive: true });
        await renamePath(backupDirectory, outputDirectory);
      } catch (restoreError) {
        throw new AggregateError(
          [error, restoreError],
          `Runtime restoration failed; previous output is in ${backupDirectory}`,
        );
      }
    }
    throw error;
  }
  if (hadPreviousOutput) await rm(backupDirectory, { force: true, recursive: true });
}

export async function buildRuntime({ outputDirectory = join(packageRoot, "dist"), validateOutput } = {}) {
  const output = resolve(outputDirectory);
  await assertSafeOutputDirectory(output);
  const staging = await mkdtemp(join(dirname(output), `${temporaryPrefix}-dist-`));
  try {
    const result = await build({
      absWorkingDir: packageRoot,
      banner: { js: banner },
      bundle: true,
      chunkNames: "chunks/[name]-[hash]",
      entryNames: "index",
      entryPoints: ["src/index.ts"],
      format: "esm",
      legalComments: "none",
      metafile: true,
      outExtension: { ".js": ".ts" },
      outdir: staging,
      packages: "external",
      platform: "node",
      sourcemap: true,
      splitting: true,
      target: "es2022",
      write: true,
    });
    validateEagerGraph(result.metafile);
    await validateGeneratedFiles(staging);
    await validateOutput?.(staging);
    await publishRuntime(staging, output);
    return result.metafile;
  } finally {
    await rm(staging, { force: true, recursive: true });
  }
}

async function statIfPresent(path) {
  try {
    return await lstat(path);
  } catch (error) {
    if (error.code === "ENOENT") return undefined;
    throw error;
  }
}

async function listFiles(directory, prefix = "") {
  const files = [];
  for (const entry of await readdir(join(directory, prefix), { withFileTypes: true })) {
    const path = join(prefix, entry.name);
    if (entry.isDirectory()) files.push(...(await listFiles(directory, path)));
    else if (entry.isFile()) files.push(path.replaceAll("\\", "/"));
    else throw new Error(`Generated runtime contains a non-regular file: ${path}`);
  }
  return files.sort();
}

const invokedPath = process.argv[1] ? pathToFileURL(resolve(process.argv[1])).href : undefined;
if (invokedPath === import.meta.url) await buildRuntime();
